import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")

    system = platform.system()
    if system == "Windows":
        cmd = "powershell -Command \"(Get-Counter '\Processor(_Total)\% Processor Time').CounterSamples.CookedValue\""
    else:
        cmd = "top -bn1 | grep 'Cpu(s)' | awk '{print $2}' | cut -d'%' -f1"

    data_points = []
    start_time = time.time()

    while time.time() - start_time < duration:
        try:
            output = subprocess.check_output(cmd, shell=True, stderr=subprocess.STDOUT)
            cpu_usage = float(output.decode().strip())
        except Exception:
            cpu_usage = 0.0

        current_record = {
            "timestamp": time.time(),
            "cpu_usage": cpu_usage
        }
        data_points.append(current_record)
        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data_points, f)
        return LOGFILE_PATH
    except IOError:
        return None

