import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    total_cpu = 0.0
    total_memory = 0

    process = subprocess.Popen(['bash', script_path], shell=True)

    try:
        ps_process = psutil.Process(process.pid)
        start_time = time.time()

        while True:
            if time.time() - start_time > timeout:
                process.terminate()
                break

            try:
                if not ps_process.is_running() or ps_process.status() == psutil.STATUS_ZOMBIE:
                    break

                cpu = ps_process.cpu_percent(interval=0)
                mem_info = ps_process.memory_info()
                rss = mem_info.rss

                total_cpu += cpu
                total_memory += rss

                time.sleep(0.1)
            except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                break
    except Exception:
        process.terminate()

    return {'CPU Usage': total_cpu, 'Memory Usage': total_memory}

